export class RetryCache {
  readonly #entries = new Map<string, Promise<unknown>>();

  getOrLoad<T>(key: string, loader: () => Promise<T>): Promise<T> {
    const existing = this.#entries.get(key) as Promise<T> | undefined;
    if (existing) return existing;

    const pending = loader();
    this.#entries.set(key, pending);
    return pending;
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { RetryCache } from "../src/retry-cache.ts";

describe("RetryCache", () => {
  it("deduplicates concurrent successful loads", async () => {
    const cache = new RetryCache();
    let calls = 0;
    const loader = async () => {
      calls += 1;
      return "profile";
    };

    const [first, second] = await Promise.all([
      cache.getOrLoad("mori", loader),
      cache.getOrLoad("mori", loader),
    ]);

    assert.equal(first, "profile");
    assert.equal(second, "profile");
    assert.equal(calls, 1);
  });

  it("retries after a rejected load", async () => {
    const cache = new RetryCache();
    let calls = 0;
    const loader = async () => {
      calls += 1;
      if (calls === 1) throw new Error("temporary failure");
      return "recovered";
    };

    await assert.rejects(cache.getOrLoad("mori", loader));
    await assert.doesNotReject(cache.getOrLoad("mori", loader));
    assert.equal(calls, 2);
  });
});

import { RetryCache } from "./retry-cache.ts";

export interface Profile {
  readonly id: string;
  readonly name: string;
}

export class ProfileService {
  readonly #cache = new RetryCache();

  constructor(readonly loadProfile: (id: string) => Promise<Profile>) {}

  getProfile(id: string): Promise<Profile> {
    return this.#cache.getOrLoad(id, () => this.loadProfile(id));
  }
}

