getOrLoad<T>(key: string, loader: () => Promise<T>): Promise<T> {
  const existing = this.#entries.get(key) as Promise<T> | undefined;
  if (existing) return existing;

  const pending = loader();
  this.#entries.set(key, pending);

  // When a load fails, remove the entry so a later call can retry. Only
  // delete if this exact promise is still the cached entry, so an older
  // rejection can never evict a newer entry that was stored since.
  pending.catch(() => {
    if (this.#entries.get(key) === pending) {
      this.#entries.delete(key);
    }
  });

  return pending;
}

